def begin(self, key: str) -> bool:
    with self._connect() as conn:
        cur = conn.execute(
            "INSERT OR IGNORE INTO idempotency (key, result, created_at) VALUES (?, NULL, ?)",
            (key, datetime.now(timezone.utc).isoformat()),
        )
        return cur.rowcount == 1          # 1 = we claimed it; 0 = someone already had it

